### 3. `script.js`

```js
const products = [
    {
        id: 1,
        name: "Áo thun nam",
        price: 150000,
        image: "https://via.placeholder.com/200x150?text=Aothun"
    },
    {
        id: 2,
        name: "Quần jean nữ",
        price: 300000,
        image: "https://via.placeholder.com/200x150?text=QuanJean"
    },
    {
        id: 3,
        name: "Giày thể thao",
        price: 500000,
        image: "https://via.placeholder.com/200x150?text=Giay"
    }
];

let cart = [];

const productListEl = document.getElementById("product-list");
const cartBtn = document.getElementById("cart-btn");
const cartSection = document.getElementById("cart-section");
const cartItemsEl = document.getElementById("cart-items");
const cartCountEl = document.getElementById("cart-count");
const totalPriceEl = document.getElementById("total-price");
const checkoutBtn = document.getElementById("checkout-btn");
const closeCartBtn = document.getElementById("close-cart-btn");

function formatPrice(price) {
    return price.toLocaleString("vi-VN") + "₫";
}

function renderProducts() {
    productListEl.innerHTML = "";
    products.forEach(product => {
        const productEl = document.createElement("div");
        productEl.className = "product";
        productEl.innerHTML = `
            <img src="${product.image}" alt="${product.name}" />
            <h3>${product.name}</h3>
            <p>Giá: ${formatPrice(product.price)}</p>
            <button data-id="${product.id}">Thêm vào giỏ</button>
        `;
        productListEl.appendChild(productEl);
    });
}

function renderCart() {
    cartItemsEl.innerHTML = "";
    if (cart.length === 0) {
        cartItemsEl.innerHTML = "<p>Giỏ hàng trống.</p>";
        totalPriceEl.textContent = "0₫";
        cartCountEl.textContent = "0";
        return;
    }

    let total = 0;
    cart.forEach(item => {
        total += item.price * item.quantity;
        const cartItemEl = document.createElement("div");
        cartItemEl.className = "cart-item";
        cartItemEl.innerHTML = `
            <span>${item.name} x ${item.quantity}</span>
            <span>${formatPrice(item.price * item.quantity)}</span>
            <button data-id="${item.id}">Xóa</button>
        `;
        cartItemsEl.appendChild(cartItemEl);
    });

    totalPriceEl.textContent = formatPrice(total);
    cartCountEl.textContent = cart.reduce((sum, item) => sum + item.quantity, 0);
}

function addToCart(productId) {
    const product = products.find(p => p.id === productId);
    if (!product) return;

    const cartItem = cart.find(item => item.id === productId);
    if (cartItem) {
        cartItem.quantity++;
    } else {
        cart.push({...product, quantity: 1});
    }
    renderCart();
}

function removeFromCart(productId) {
    cart = cart.filter(item => item.id !== productId);
    renderCart();
}

productListEl.addEventListener("click", e => {
    if (e.target.tagName === "BUTTON") {
        const id = parseInt(e.target.dataset.id);
        addToCart(id);
    }
});

