// src/parser.ts

// Import 'marked' only if used for additional parsing logic.
// import { marked, Token } from 'marked';
// import type { Tokens } from 'marked';

// Import the generated parser
// eslint-disable-next-line @typescript-eslint/no-var-requires
const MarkdownBlockParser = require('./generated-markdown-parser.cjs');

// Explicit block regexes
export const explicitCommentBlockRegex = /\/\*\s*START OF\s*(?<path>.*?)\s*\*\/\r?\n?(?<content>.*?)\r?\n?\/\*\s*END OF\s*\1\s*\*\//gs;
export const explicitTagBlockRegex = /<file\s+(?:path|name|filename)\s*=\s*["'](?<path>.*?)["']\s*>\r?\n?(?<content>.*?)\r?\n?<\/file>/gis;

// Type definitions
export type FileData = {
    content: string;
    format: string; // e.g., "Comment Block", "Tag Block", "Markdown Block"
};
export type FilesMap = Map<string, FileData>;

// Parsing Functions

/** Extracts file path and content from explicit markers */
export function extractExplicitBlocks(
    input: string,
    regex: RegExp,
    formatName: string,
    filesToWrite: FilesMap
): string {
    let remainingInput = input;
    const matches = [...input.matchAll(regex)];
    for (const match of matches) {
        const filePath = match.groups?.path?.trim();
        const contentMatch = match.groups?.content;
        const fullMatch = match[0];

        if (filePath && contentMatch !== undefined && fullMatch) {
            const normalizedPath = filePath.replace(/\\/g, '/');
            let content = contentMatch.replace(/^\r?\n/, '').replace(/\r?\n\s*$/, '');
            if (filesToWrite.has(normalizedPath)) {
                console.warn(`[${formatName}] Overwriting prior definition for ${normalizedPath}`);
            }
            filesToWrite.set(normalizedPath, { content, format: formatName });
            remainingInput = remainingInput.replace(fullMatch, `\n[LLM_APPLY_Processed ${formatName} for ${normalizedPath}]\n`);
        } else {
            console.warn(`[${formatName}] Failed to extract path or content from block: ${fullMatch?.substring(0, 100)}...`);
        }
    }
    return remainingInput;
}

/** Extracts file paths and content using the PEG Markdown parser */
export function extractMarkdownBlocksWithPeg(
    markdownInput: string,
    filesToWrite: FilesMap
): void {
    const formatName = "Markdown Block";
    try {
        const parsedBlocks: Array<{ path: string; content: string; format: string }> = MarkdownBlockParser.parse(markdownInput);

        for (const block of parsedBlocks) {
            const normalizedPath = block.path;
            const existingData = filesToWrite.get(normalizedPath);

            if (existingData) {
                if (existingData.format !== formatName) {
                    console.log(`[${formatName}] Skipping ${normalizedPath} (defined by ${existingData.format})`);
                } else {
                    console.warn(`[${formatName}] Overwriting prior Markdown definition for ${normalizedPath}`);
                    filesToWrite.set(normalizedPath, { content: block.content, format: formatName });
                }
            } else {
                console.log(`[${formatName}] Found: ${normalizedPath}`);
                filesToWrite.set(normalizedPath, { content: block.content, format: formatName });
            }
        }
    } catch (error: any) {
        if (error.location && error.format) {
            console.error(`Error parsing Markdown blocks:\n${error.format([{ source: "stdin", text: markdownInput }])}`);
        } else if (error.location) {
            console.error(`Error parsing Markdown blocks at Line ${error.location.start.line}, Column ${error.location.start.column}: ${error.message}`);
            const lines = markdownInput.split('\n');
            const errorLineIndex = error.location.start.line - 1;
            const contextStart = Math.max(0, errorLineIndex - 1);
            const contextEnd = Math.min(lines.length, errorLineIndex + 2);
            const context = lines.slice(contextStart, contextEnd).join('\n');
            console.error(`Context:\n---\n${context}\n---`);
        } else {
            console.error(`Error parsing Markdown blocks: ${error.message}`);
        }
    }
}
