            if not conversation_messages or len(conversation_messages) < 2:
                return False
            user_responses = [msg["user"] for msg in conversation_messages if "user" in msg]
            if not user_responses:
                return False
            last_responses = user_responses[-2:]
            awake = any(len(response.split()) > 5 for response in last_responses) and \
                    all("?" not in response for response in last_responses)
            return awake
        except Exception as e:
            print(f"Error checking wakefulness: {str(e)}")
            return False

    def _summary_loop(self):
        print("[Summary thread started]")
        while self.running:
            try:
                now = time.time()
                if (now - self.last_summary_time) >= SUMMARY_INTERVAL:
