        self.summary_thread = threading.Thread(target=self._summary_loop, daemon=True)
        self.summary_thread.start()

        try:
            with self.conversation_lock:
                self.current_conversation = {
                    "start_time": time.time(),
                    "timestamp": datetime.now().isoformat(),
                    "messages": [],
                    "woke_up": False
                }
            self.last_user_reply_time = time.time()

            self.play_alarm()

            try:
                print("Assistant generating initial prompt...")
                initial_msg, action = self.chat_with_llm()
                if initial_msg:
                    print(f"Assistant: {initial_msg}")
                    with self.conversation_lock:
                        self.current_conversation["messages"].append({"assistant": initial_msg})
                    if action:
                        self.handle_escape_sequence(action)
                self.last_summary_time = time.time()
            except Exception as e:
                print(f"Error during initial LLM call: {str(e)}")
                fallback_initial_msg = "This is your wake-up call. Are you ready to report?"
                print(f"Assistant: {fallback_initial_msg}")
                with self.conversation_lock:
                    self.current_conversation["messages"].append({"assistant": fallback_initial_msg})

            with patch_stdout():
                while self.alarm_active:
                    try:
                        user_input = self.session.prompt("You: ")
                        self.last_user_reply_time = time.time()

                        if user_input.strip():
                            with self.conversation_lock:
                                if self.current_conversation:
                                    self.current_conversation["messages"].append({"user": user_input})
                                else:
                                    print("Error: Current conversation is None. Cannot add message.")
                                    continue

                            llm_response, action_taken = self.chat_with_llm(user_input)

                            if llm_response:
                                print(f"Assistant: {llm_response}")
                                with self.conversation_lock:
                                    if self.current_conversation:
                                        self.current_conversation["messages"].append({"assistant": llm_response})
                                    else:
                                        print("Error: Current conversation is None. Cannot add assistant message.")

                            if action_taken:
                                self.handle_escape_sequence(action_taken)
                                if not self.alarm_active:
                                    break
                        else:
                            print("(Empty input ignored)")

                    except EOFError:
                        print("\nEOF received. Shutting down...")
                        self.running = False
                        break
                    except KeyboardInterrupt:
                        print("\nKeyboardInterrupt received. Shutting down...")
                        self.running = False
                        break
                    except Exception as e:
                        print(f"Error in main loop: {str(e)}")
                        time.sleep(1)

        except Exception as e:
            print(f"Fatal error in run method: {str(e)}")
        finally:
            self.cleanup()
            if self.alarm_active:
                print("\nWarning: Exited while alarm was still marked as active!")
            else:
                print("\nAlarm stopped. Have a productive day!")

if __name__ == "__main__":
    app = AlarmChatApp()
    app.run()
```

