import { useEffect, useState } from 'react';

export const useBalloonAnimation = () => {
  const [balloons, setBalloons] = useState<Balloon[]>([]);

  useEffect(() => {
    const initialBalloons = Array.from({ length: BALLOON_COUNT }).map((_, i) => createBalloon(i));
    setBalloons(initialBalloons);
  }, []);

  useEffect(() => {
    let animationFrameId: number;
    const animate = () => {
      setBalloons(prev =>
        prev.map(b => {
          if (b.popped) return b;
          const newY = b.y - b.speed;
          if (newY < -(b.size * 1.5)) {
            return { ...createBalloon(b.id), y: window.innerHeight + b.size };
          }
          return { ...b, y: newY };
        })
      );
      animationFrameId = requestAnimationFrame(animate);
    };

    animationFrameId = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(animationFrameId);
  }, []);

  return { balloons, setBalloons };
};
```

