using System;
using System.Collections.Generic;
using System.IO;

public class AudioFileProcessor
{
    public static List<byte[]> GetAudioFilesInOrder(string audioFolder, int start, int stop)
    {
        // Get all MP3 files in the folder
        string[] allFiles = Directory.GetFiles(audioFolder, "*.mp3");

        // Collect valid files with numeric filenames within the range
        var validFiles = new List<(int Number, string FilePath)>();

        foreach (var filePath in allFiles)
        {
            // Extract filename without extension
            string fileName = Path.GetFileNameWithoutExtension(filePath);

            // Try to parse the filename as integer
            if (int.TryParse(fileName, out int number))
            {
                // Check if within the desired range
                if (number >= start && number <= stop)
                {
                    validFiles.Add((number, filePath));
                }
            }
        }

        // Sort files numerically
        validFiles.Sort((a, b) => a.Number.CompareTo(b.Number));

        // Read each file's bytes and store in list
        List<byte[]> audioFiles = new List<byte[]>();
        foreach (var file in validFiles)
        {
            audioFiles.Add(File.ReadAllBytes(file.FilePath));
        }

        return audioFiles;
    }
}
